def check_todo_fixme(repo_path):
    """
    This function checks for TODO or FIXME comments in all files within a given repository path.
    It returns a report containing the file paths and line numbers where these comments are found.

    :param repo_path: The root directory of the repository to be checked.
    :return: A dictionary with file paths as keys and lists of tuples (line_number, comment) as values.
    """
    import os
    import re

    report = {}
    todo_fixme_pattern = re.compile(r'\b(TODO|FIXME)\b')

    for root, _, files in os.walk(repo_path):
        for file in files:
            if not file.endswith(('.py', '.js', '.java', '.cpp', '.c', '.h')):
                continue

            file_path = os.path.join(root, file)
            with open(file_path, 'r', encoding='utf-8') as f:
                lines = f.readlines()
                for line_number, line in enumerate(lines, start=1):
                    if todo_fixme_pattern.search(line):
                        if file_path not in report:
                            report[file_path] = []
                        report[file_path].append((line_number, line.strip()))

    return report

if __name__ == '__main__':
    repo_path = '/path/to/repo'
    report = check_todo_fixme(repo_path)
    for file_path, issues in report.items():
        print(f'File: {file_path}')
        for line_number, comment in issues:
            print(f'  Line {line_number}: {comment}')
  },
  "mode": "overwrite"
}
