        return result.stdout.strip()
    except subprocess.CalledProcessError as e:
        print(f"Error getting last commit: {e}")
        return None

def get_uncommitted_files():
    """Get a list of uncommitted files."""
    try:
        result = subprocess.run(['git', 'status', '--porcelain'], check=True, text=True, capture_output=True)
        uncommitted_files = [line.strip() for line in result.stdout.splitlines() if line]
        return uncommitted_files
    except subprocess.CalledProcessError as e:
        print(f"Error getting uncommitted files: {e}")
        return None

def generate_report():
    """Generate a report of the current git branch, last commit, and uncommitted files."""
    branch = get_git_branch()
    last_commit = get_last_commit()
    uncommitted_files = get_uncommitted_files()

